--- EditorSuggest:
--- nodeTagHotkey default:
constants.ts:120:  nodeTagHotkey: "\\",
types.ts:70:  nodeTagHotkey: string;
--- getSearchableNodes:
   * owns that fallback. Call once per open, not per keystroke: the scan is the
   * pipeline's most expensive step, and ignoring the type filter keeps filter changes free.
   * Both paths only check that `nodeTypeId` exists, so unconfigured types are dropped here.
   */
  getSearchableNodes = (nodeTypes: DiscourseNode[]): SearchableNode[] => {
    const configuredTypeIds = new Set(nodeTypes.map((nodeType) => nodeType.id));
    const nodes: SearchableNode[] = [];

    for (const file of this.getFilesWithNodeTypeId()) {
      const frontmatter: Record<string, unknown> | undefined =
        this.app.metadataCache.getFileCache(file)?.frontmatter;
      const nodeTypeId = frontmatter?.nodeTypeId;
      if (
        typeof nodeTypeId !== "string" ||
        !configuredTypeIds.has(nodeTypeId)
      ) {
        continue;
      }

      nodes.push({ file, title: file.basename, nodeTypeId });
    }

    return nodes;
  };

  /** One pass over the metadata cache's tag index; only files with a hit are read. */
--- insertLink:
import { App, MarkdownView, TFile, type EditorPosition } from "obsidian";

/** Held rather than re-looked-up, so the link lands in the pre-open note. */
export type EditorInsertTarget = {
  view: MarkdownView;
  from: EditorPosition;
  to: EditorPosition;
};

/**
 * Call before the modal mounts, while the editor still owns the cursor.
 * `hasFocus()` is not part of the gate: opening the search from the command
 * palette means that palette already took focus.
 */
export const snapshotInsertTarget = (app: App): EditorInsertTarget | null => {
  const view = app.workspace.getActiveViewOfType(MarkdownView);
  // Reading mode has no cursor.
  if (!view || !view.file || view.getMode() !== "source") return null;

  const { editor } = view;
  return {
    view,
    // A selection is replaced rather than left beside the link.
    from: editor.getCursor("from"),
    to: editor.getCursor("to"),
  };
};

/** `generateMarkdownLink` is what honours the vault's link-format settings. */
export const insertLinkAtInsertTarget = ({
  app,
  file,
  target,
}: {
  app: App;
  file: TFile;
  target: EditorInsertTarget;
}): void => {
  const { view, from, to } = target;
  const sourceFile = view.file;
  if (!sourceFile) return;

  const link = app.fileManager.generateMarkdownLink(file, sourceFile.path);
  const { editor } = view;
  editor.replaceRange(link, from, to);

  app.workspace.setActiveLeaf(view.leaf, { focus: true });
  editor.setCursor({ line: from.line, ch: from.ch + link.length });
  editor.focus();
};
--- tag hotkey handler:
    this.helpMenuStatusBarItem = item;
  }

  private setupNodeTagHotkey() {
    const nodeTagHotkeyExtension = EditorView.domEventHandlers({
      keydown: (event: KeyboardEvent) => {
        // Access settings dynamically to handle changes
        const hotkey = this.settings.nodeTagHotkey;

        if (!hotkey || event.key !== hotkey) {
          return false;
        }
        event.preventDefault();
        event.stopPropagation();

        this.activeNodePopover?.close();
        this.activeNodePopover = null;

        const activeView = this.app.workspace.getActiveViewOfType(MarkdownView);
        if (activeView?.editor) {
          const editor = activeView.editor;
          const selectedText = editor.getSelection();

          if (selectedText && selectedText.trim().length > 0) {
            const picker = new InlineNodeTypePicker({
              editor,
              nodeTypes: this.settings.nodeTypes,
              plugin: this,
              selectedText: selectedText.trim(),
            });
            this.activeNodePopover = picker;
            picker.open();
          } else {
            const popover = new NodeTagSuggestPopover(
              editor,
              this.settings.nodeTypes,
            );
            this.activeNodePopover = popover;
            popover.open();
          }
        }

        return true;
      },
    });

    this.registerEditorExtension(nodeTagHotkeyExtension);

    this.registerEditorExtension(createImageEmbedHoverExtension(this));

    this.registerEditorExtension(createWikilinkDragExtension(this));

