89	      "border-[var(--background-modifier-border)]",
90	      "bg-[var(--background-primary)]",
91	      "p-3",
92	      "shadow-lg",
93	    );
94	
95	    // CurrentRelationships renders nothing when empty, leaving a bare button.
96	    if (relationCount === 0) {
97	      this.emptyEl = this.containerEl.createDiv({
98	        cls: "mb-2 text-sm text-[var(--text-muted)]",
99	        text: EMPTY_MESSAGE,
100	      });
101	      // It lives outside React, so RelationshipSection cannot clear it when the
102	      // first relation is added from this very popover.
103	      this.cleanupListeners.push(
104	        plugin.relationsIndex.onChange(() => {
105	          if (countRelationsForFile(plugin, file) === 0) return;
106	          this.emptyEl?.remove();
107	          this.emptyEl = null;
108	        }),
109	      );
110	    }
111	
112	    const reactHost = this.containerEl.createDiv();
113	    this.root = createRoot(reactHost);
114	    this.root.render(
115	      <PluginProvider plugin={this.plugin}>
116	        <RelationshipSection activeFile={file} />
117	      </PluginProvider>,
118	    );
119	
120	    // A React 18 root commits async, so measure again after paint and on resize.
121	    positionPopover(this.containerEl, anchor);
122	    this.reposition = () => positionPopover(this.containerEl, anchor);
123	    this.win.requestAnimationFrame(this.reposition);
124	    this.resizeObserver = new ResizeObserver(this.reposition);
125	    this.resizeObserver.observe(this.containerEl);
126	
127	    this.registerDismissListeners();
128	  }
129	
130	  private registerDismissListeners(): void {
131	    const doc = this.containerEl.ownerDocument;
132	    const closeIfOutside = (event: MouseEvent): void => {
133	      if (this.containerEl.contains(event.target as Node)) return;
134	      // AbstractInputSuggest mounts its list on body, so a click picking a node
135	      // for a new relation would otherwise dismiss the popover behind it.
136	      if ((event.target as Element)?.closest?.(".suggestion-container")) return;
137	      this.close();
138	    };
139	    const closeOnEscape = (event: KeyboardEvent): void => {
140	      if (event.key !== "Escape") return;
141	      event.preventDefault();
142	      this.close();
143	    };
144	    // Scrolling the note dismisses; scrolling the popover's own content must not.
145	    const closeOnScroll = (event: Event): void => {
146	      if (this.containerEl.contains(event.target as Node)) return;
147	      this.close();
148	    };
149	
150	    // Deferred so the opening click is not read as an outside click.
151	    const attach = this.win.setTimeout(() => {
152	      doc.addEventListener("click", closeIfOutside, true);
153	    }, 0);
154	
155	    doc.addEventListener("keydown", closeOnEscape);
156	    // Capture phase: scrolling happens inside panes, not on window.
157	    doc.addEventListener("scroll", closeOnScroll, true);
158	
159	    this.cleanupListeners.push(() => {
160	      this.win.clearTimeout(attach);
161	      doc.removeEventListener("click", closeIfOutside, true);
162	      doc.removeEventListener("keydown", closeOnEscape);
163	      doc.removeEventListener("scroll", closeOnScroll, true);
164	    });
165	  }
166	
167	  close(): void {
168	    for (const cleanup of this.cleanupListeners) cleanup();
169	    this.cleanupListeners = [];
170	    this.resizeObserver?.disconnect();
171	    this.resizeObserver = null;
172	    // Deferred: unmounting during React's event handling warns.
173	    const root = this.root;
174	    this.win.setTimeout(() => root.unmount(), 0);
175	    this.containerEl.remove();
176	    if (activePopover === this) activePopover = null;
177	  }
178	}
179	
180	let activePopover: DiscourseContextPopover | null = null;
181	
182	export const openDiscourseContextPopover = (options: PopoverOptions): void => {
183	  activePopover?.close();
184	  activePopover = new DiscourseContextPopover(options);
185	};
186	
187	export const closeDiscourseContextPopover = (): void => {
188	  activePopover?.close();
189	};
