  folderPath?: string;
  created: number;
  modified: number;
  importedFromRid?: string;
  authorId?: number;
};

export type ImportStatus = "provisional" | "accepted";

export type DiscourseRelationType = {
  id: string;
  label: string;
  complement: string;
  color: TldrawColorName;
  created: number;
  modified: number;
  importedFromRid?: string;
  status?: ImportStatus;
  authorId?: number;
};

export type DiscourseRelation = {
  id: string;
  sourceId: string;
  destinationId: string;
