  groups,
  activeIndex,
  onSelect,
  onHover,
}: NodeSummonListProps) => {
  const activeRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    activeRef.current?.scrollIntoView({ block: "nearest" });
