// ENG-893 slice 1: node summon menu opens on "@", narrows, inserts, closes.
const MENU = ".dg-node-summon-menu";
const ITEM = `${MENU} .suggestion-item`;
const SCRATCH = "summon-scratch.md";

const KEYS = {
  Enter: { key: "Enter", code: "Enter", windowsVirtualKeyCode: 13, nativeVirtualKeyCode: 13 },
  ArrowDown: { key: "ArrowDown", code: "ArrowDown", windowsVirtualKeyCode: 40, nativeVirtualKeyCode: 40 },
  Backspace: { key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 },
};

const openScratch = async (ctx, content, { livePreview = false } = {}) => {
  const { client, json } = ctx;
  const p = await ctx.writeNote(SCRATCH, content);
  await client.evaluate(`return (async () => {
    const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(p)}),
      { state: { mode: "source", source: ${json(!livePreview)} } });
    app.workspace.setActiveLeaf(leaf, { focus: true });
    const editor = leaf.view.editor;
    editor.focus();
    const last = editor.lastLine();
    editor.setCursor({ line: last, ch: editor.getLine(last).length });
    return true;
  })();`);
  return p;
};

const menuState = ({ client, json }) =>
  client.evaluate(`return (() => {
    const menu = document.querySelector(${json(MENU)});
    if (!menu) return { open: false };
    const items = [...menu.querySelectorAll(".suggestion-item")];
    return {
      open: true,
      headers: [...menu.querySelectorAll(".suggestion > div:not(.suggestion-item)")].map((h) => h.textContent),
      items: items.map((i) => i.textContent),
      selected: items.findIndex((i) => i.classList.contains("is-selected")),
      empty: menu.querySelector(".suggestion-empty")?.textContent ?? null,
    };
  })();`);

const editorText = ({ client }) =>
  client.evaluate(`return app.workspace.activeLeaf.view.editor.getValue();`);

const waitOpen = (ctx) =>
  ctx.client.waitFor(`!!document.querySelector(${ctx.json(MENU)})`, { label: "menu open" });
const waitClosed = (ctx) =>
  ctx.client.waitFor(`!document.querySelector(${ctx.json(MENU)})`, { label: "menu closed" });

// A configured discourse node outside _verify, so results have something real.
const nodeTitle = ({ client }) =>
  client.evaluate(`return app.vault.getMarkdownFiles()
    .find((f) => !f.path.startsWith("_verify/") && app.metadataCache.getFileCache(f)?.frontmatter?.nodeTypeId)
    ?.basename;`);

export default [
  {
    name: "Opens grouped at line start (Live Preview)",
    input: "empty note in Live Preview; type @",
    expected: "menu opens with type headers, ≤10 items per type, first item selected",
    run: async (ctx) => {
      await openScratch(ctx, "", { livePreview: true });
      await ctx.client.typeText("@");
      await waitOpen(ctx);
      return menuState(ctx);
    },
    expect: (s) => ({
      pass: s.open && s.headers.length > 0 && s.items.length > 0 && s.selected === 0,
      actual: `headers=${JSON.stringify(s.headers)} items=${s.items?.length} selected=${s.selected}`,
    }),
  },
  {
    name: "Does not open mid-word",
    input: "type me@lab in Source mode",
    expected: "no menu",
    run: async (ctx) => {
      await openScratch(ctx, "");
      await ctx.client.typeText("me@lab");
      await new Promise((r) => setTimeout(r, 500));
      return { state: await menuState(ctx), text: await editorText(ctx) };
    },
    expect: (a) => ({ pass: !a.state.open && a.text === "me@lab", actual: `open=${a.state.open} text=${a.text}` }),
  },
  {
    name: "Narrows, Enter inserts link after space",
    input: "type 'see @' + first 5 chars of a node title, press Enter",
    expected: "results narrow to the title; link to it replaces @query; menu closes; cursor after link",
    setup: async (ctx) => ({ title: await nodeTitle(ctx) }),
    run: async (ctx, { title }) => {
      const p = await openScratch(ctx, "");
      await ctx.client.typeText(`see @${title.slice(0, 5)}`);
      await waitOpen(ctx);
      const state = await menuState(ctx);
      await ctx.client.key(KEYS.Enter);
      await waitClosed(ctx);
      const text = await editorText(ctx);
      const cursor = await ctx.client.evaluate(`return app.workspace.activeLeaf.view.editor.getCursor();`);
      return { title, state, text, cursor, p };
    },
    expect: (a) => {
      const inserted = a.text.slice("see ".length);
      const pass =
        a.state.items.includes(a.title) &&
        a.text.startsWith("see ") &&
        inserted.includes(a.title) &&
        /^(\[\[.+\]\]|\[.*\]\(.+\))$/.test(inserted) &&
        a.cursor.ch === a.text.length;
      return { pass, actual: `items=${a.state.items.length} text=${a.text} cursor=${a.cursor.ch}` };
    },
  },
  {
    name: "ArrowDown moves the selection",
    input: "type @, ArrowDown twice",
    expected: "selected index goes 0 → 1 → 2 (or wraps)",
    run: async (ctx) => {
      await openScratch(ctx, "");
      await ctx.client.typeText("@");
      await waitOpen(ctx);
      const seq = [(await menuState(ctx)).selected];
      for (let i = 0; i < 2; i++) {
        await ctx.client.key(KEYS.ArrowDown);
        await new Promise((r) => setTimeout(r, 100));
        seq.push((await menuState(ctx)).selected);
      }
      const { items } = await menuState(ctx);
      return { seq, count: items.length, text: await editorText(ctx) };
    },
    expect: (a) => {
      const want = [0, 1 % a.count, 2 % a.count];
      return {
        pass: JSON.stringify(a.seq) === JSON.stringify(want) && a.text === "@",
        actual: `seq=${a.seq} count=${a.count} text=${a.text}`,
      };
    },
  },
  {
    name: "Escape closes, text kept",
    input: "type @arp, press Escape",
    expected: "menu closes; '@arp' stays in the note",
    run: async (ctx) => {
      await openScratch(ctx, "");
      await ctx.client.typeText("@arp");
      await waitOpen(ctx);
      await ctx.client.pressEscape();
      await waitClosed(ctx);
      return editorText(ctx);
    },
    expect: (text) => ({ pass: text === "@arp", actual: `text=${text}` }),
  },
  {
    name: "Deleting the trigger closes",
    input: "type @a, Backspace twice",
    expected: "menu closes once @ is gone",
    run: async (ctx) => {
      await openScratch(ctx, "");
      await ctx.client.typeText("@a");
      await waitOpen(ctx);
      await ctx.client.key(KEYS.Backspace);
      const afterOne = (await menuState(ctx)).open;
      await ctx.client.key(KEYS.Backspace);
      await waitClosed(ctx);
      return { afterOne, text: await editorText(ctx) };
    },
    expect: (a) => ({ pass: a.afterOne && a.text === "", actual: `open after 1st=${a.afterOne} text='${a.text}'` }),
  },
];

