// ENG-893 slice 1: node summon menu opens on "@", narrows, inserts, closes.
const MENU = ".dg-node-summon-menu";
const ITEM = `${MENU} .suggestion-item`;
const SCRATCH = "summon-scratch.md";

const KEYS = {
  Enter: { key: "Enter", code: "Enter", windowsVirtualKeyCode: 13, nativeVirtualKeyCode: 13 },
  ArrowDown: { key: "ArrowDown", code: "ArrowDown", windowsVirtualKeyCode: 40, nativeVirtualKeyCode: 40 },
  Backspace: { key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 },
};

const openScratch = async (ctx, content, { livePreview = false } = {}) => {
  const { client, json } = ctx;
  const p = await ctx.writeNote(SCRATCH, content);
  await client.evaluate(`return (async () => {
    const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(p)}),
      { state: { mode: "source", source: ${json(!livePreview)} } });
    app.workspace.setActiveLeaf(leaf, { focus: true });
    const editor = leaf.view.editor;
    editor.focus();
    const last = editor.lastLine();
    editor.setCursor({ line: last, ch: editor.getLine(last).length });
    return true;
  })();`);
  return p;
};

const menuState = ({ client, json }) =>
  client.evaluate(`return (() => {
    const menu = document.querySelector(${json(MENU)});
    if (!menu) return { open: false };
    const items = [...menu.querySelectorAll(".suggestion-item")];
    return {
      open: true,
      headers: [...menu.querySelectorAll(".suggestion > div:not(.suggestion-item)")].map((h) => h.textContent),
      items: items.map((i) => i.textContent),
      selected: items.findIndex((i) => i.classList.contains("is-selected")),
      empty: menu.querySelector(".suggestion-empty")?.textContent ?? null,
    };
  })();`);

const editorText = ({ client }) =>
  client.evaluate(`return app.workspace.activeLeaf.view.editor.getValue();`);

const waitOpen = async (ctx) => {
  try {
    await ctx.client.waitFor(`!!document.querySelector(${ctx.json(MENU)})`, { label: "menu open", timeoutMs: 3000 });
  } catch {
    const probe = await ctx.client.evaluate(`return (() => { const l = app.workspace.activeLeaf; const e = l?.view?.editor;
      return { file: l?.view?.file?.path, text: e?.getValue(), cursor: e?.getCursor(), focus: e?.hasFocus(),
        active: document.activeElement?.className, leaves: app.workspace.getLeavesOfType("markdown").length }; })();`);
    throw new Error("menu never opened: " + JSON.stringify(probe));
  }
};
const waitClosed = (ctx) =>
  ctx.client.waitFor(`!document.querySelector(${ctx.json(MENU)})`, { label: "menu closed" });

// A configured discourse node outside _verify, so results have something real.
const nodeTitle = ({ client }) =>
  client.evaluate(`return app.vault.getMarkdownFiles()
    .find((f) => !f.path.startsWith("_verify/") && app.metadataCache.getFileCache(f)?.frontmatter?.nodeTypeId)
    ?.basename;`);

export default [
  {
    name: "Opens grouped at line start (Live Preview)",
    input: "empty note in Live Preview; type @",
    expected: "menu opens with type headers, ≤10 items per type, first item selected",
    run: async (ctx) => {
      await openScratch(ctx, "", { livePreview: true });
      await ctx.client.typeText("@");
      await waitOpen(ctx);
      return menuState(ctx);
    },
    expect: (s) => ({
      pass: s.open && s.headers.length > 0 && s.items.length > 0 && s.selected === 0,
      actual: `headers=${JSON.stringify(s.headers)} items=${s.items?.length} selected=${s.selected}`,
    }),
  },
  {
    name: "Does not open mid-word",
    input: "type me@lab in Source mode",
    expected: "no menu",
    run: async (ctx) => {
      await openScratch(ctx, "");
      await ctx.client.typeText("me@lab");
      await new Promise((r) => setTimeout(r, 500));
      return { state: await menuState(ctx), text: await editorText(ctx) };
    },
    expect: (a) => ({ pass: !a.state.open && a.text === "me@lab", actual: `open=${a.state.open} text=${a.text}` }),
  },
  {
    name: "Narrows, Enter inserts link after space",
    input: "type 'see @' + first 5 chars of a node title, press Enter",
    expected: "results narrow to the title; link to it replaces @query; menu closes; cursor after link",
    setup: async (ctx) => ({ title: await nodeTitle(ctx) }),
    run: async (ctx, { title }) => {
      const p = await openScratch(ctx, "");
      await ctx.client.typeText(`see @${title.slice(0, 5)}`);
      await waitOpen(ctx);
      const state = await menuState(ctx);
      await ctx.client.key(KEYS.Enter);
      await waitClosed(ctx);
      const text = await editorText(ctx);
      const cursor = await ctx.client.evaluate(`return app.workspace.activeLeaf.view.editor.getCursor();`);
      return { title, state, text, cursor, p };
    },
    expect: (a) => {
      const inserted = a.text.slice("see ".length);
      const pass =
        a.state.items.length > 0 &&
        a.state.items.every((t) => t.toLowerCase().includes(a.title.slice(0, 5).toLowerCase())) &&
        a.text.startsWith("see ") &&
        inserted.includes(a.state.items[0]) &&
        /^(\[\[.+\]\]|\[.*\]\(.+\))$/.test(inserted) &&
        a.cursor.ch === a.text.length;
      return { pass, actual: `items=${a.state.items.length} text=${a.text} cursor=${a.cursor.ch}` };
    },
  },
  {
    name: "ArrowDown moves the selection",
    input: "type @, ArrowDown twice",
    expected: "selected index goes 0 → 1 → 2 (or wraps)",
    run: async (ctx) => {
      await openScratch(ctx, "");
      await ctx.client.typeText("@");
      await waitOpen(ctx);
      const seq = [(await menuState(ctx)).selected];
      for (let i = 0; i < 2; i++) {
        await ctx.client.key(KEYS.ArrowDown);
        await new Promise((r) => setTimeout(r, 100));
        seq.push((await menuState(ctx)).selected);
      }
      const { items } = await menuState(ctx);
      return { seq, count: items.length, text: await editorText(ctx) };
    },
    expect: (a) => {
      const want = [0, 1 % a.count, 2 % a.count];
      return {
        pass: JSON.stringify(a.seq) === JSON.stringify(want) && a.text === "@",
        actual: `seq=${a.seq} count=${a.count} text=${a.text}`,
      };
    },
  },
  {
    name: "Escape closes, text kept",
    input: "type @arp, press Escape",
    expected: "menu closes; '@arp' stays in the note",
    run: async (ctx) => {
      await openScratch(ctx, "");
      await ctx.client.typeText("@arp");
      await waitOpen(ctx);
      await ctx.client.pressEscape();
      await waitClosed(ctx);
      return editorText(ctx);
    },
    expect: (text) => ({ pass: text === "@arp", actual: `text=${text}` }),
  },
  {
    name: "Deleting the trigger closes",
    input: "type @a, Backspace twice",
    expected: "menu closes once @ is gone",
    run: async (ctx) => {
      await openScratch(ctx, "");
      await ctx.client.typeText("@a");
      await waitOpen(ctx);
      await ctx.client.key(KEYS.Backspace);
      const afterOne = (await menuState(ctx)).open;
      await ctx.client.key(KEYS.Backspace);
      await waitClosed(ctx);
      return { afterOne, text: await editorText(ctx) };
    },
    expect: (a) => ({ pass: a.afterOne && a.text === "", actual: `open after 1st=${a.afterOne} text='${a.text}'` }),
  },
];

import { EditorView, type ViewUpdate } from "@codemirror/view";
import type DiscourseGraphPlugin from "~/index";
import {
  closeNodeSummonMenu,
  getActiveNodeSummonMenu,
  openNodeSummonMenu,
} from "~/components/NodeSummonMenu";
import { getTypedTriggerStart } from "~/utils/nodeSearchTrigger";

// Keeps the open menu's query in sync, or closes it once the trigger is gone.
const updateOpenMenu = (update: ViewUpdate): boolean => {
  const menu = getActiveNodeSummonMenu();
  if (!menu || menu.view !== update.view) return false;
  if (!update.docChanged && !update.selectionSet) return true;

  const { doc, selection } = update.state;
  const triggerFrom = update.changes.mapPos(menu.triggerFrom);
  const queryFrom = triggerFrom + menu.trigger.length;
  const head = selection.main.head;

  const triggerIntact =
    queryFrom <= doc.length &&
    doc.sliceString(triggerFrom, queryFrom) === menu.trigger;
  const cursorInQuery =
    selection.main.empty &&
    head >= queryFrom &&
    doc.lineAt(head).number === doc.lineAt(triggerFrom).number;

  if (!triggerIntact || !cursorInQuery) {
    closeNodeSummonMenu();
    return true;
  }

  menu.triggerFrom = triggerFrom;
  menu.setQuery(doc.sliceString(queryFrom, head));
  return true;
};

export const createNodeSummonExtension = (plugin: DiscourseGraphPlugin) =>
  EditorView.updateListener.of((update) => {
    if (updateOpenMenu(update)) return;

    // Only typing opens it; moving the cursor back into existing `@text` does not.
    const typed = update.transactions.some((tr) => tr.isUserEvent("input.type"));
    if (!update.docChanged || !typed) return;

    const { doc, selection } = update.state;
    if (!selection.main.empty) return;
    const head = selection.main.head;
    const line = doc.lineAt(head);
    const trigger = plugin.settings.nodeSearchTrigger;
    const start = getTypedTriggerStart({
      lineBeforeCursor: doc.sliceString(line.from, head),
      trigger,
    });
    if (start === null) return;

    openNodeSummonMenu({
      plugin,
      view: update.view,
      triggerFrom: line.from + start,
      trigger,
    });
  });

import { Fragment, useEffect, useRef } from "react";
import { createRoot, type Root } from "react-dom/client";
import { editorInfoField, Scope } from "obsidian";
import type { EditorView } from "@codemirror/view";
import type DiscourseGraphPlugin from "~/index";
import { QueryEngine, type SearchableNode } from "~/services/QueryEngine";
import {
  groupNodesForSummonMenu,
  type SummonMenuGroup,
} from "~/utils/nodeSummonResults";

const VIEWPORT_MARGIN = 8;

type NodeSummonListProps = {
  groups: SummonMenuGroup[];
  activeIndex: number;
  onSelect: (index: number) => void;
  onHover: (index: number) => void;
};

const NodeSummonList = ({
  groups,
  activeIndex,
  onSelect,
  onHover,
}: NodeSummonListProps) => {
  const activeRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    activeRef.current?.scrollIntoView({ block: "nearest" });
  }, [activeIndex]);

  if (groups.length === 0) {
    return <div className="suggestion-empty">No matching nodes</div>;
  }

  let index = 0;
  return (
    <div className="suggestion">
      {groups.map((group) => (
        <Fragment key={group.nodeType.id}>
          <div className="px-3 pb-1 pt-2 text-xs font-semibold text-[var(--text-muted)]">
            {group.nodeType.name}
          </div>
          {group.nodes.map((node) => {
            const itemIndex = index++;
            const isActive = itemIndex === activeIndex;
            return (
              <div
                key={node.file.path}
                ref={isActive ? activeRef : undefined}
                className={`suggestion-item${isActive ? " is-selected" : ""}`}
                // Keeps focus in the editor, so the cursor stays after the query.
                onMouseDown={(event) => event.preventDefault()}
                onMouseMove={() => onHover(itemIndex)}
                onClick={() => onSelect(itemIndex)}
              >
                {node.title}
              </div>
            );
          })}
        </Fragment>
      ))}
    </div>
  );
};

type NodeSummonMenuOptions = {
  plugin: DiscourseGraphPlugin;
  view: EditorView;
  triggerFrom: number;
  trigger: string;
};

class NodeSummonMenu {
  readonly view: EditorView;
  readonly trigger: string;
  triggerFrom: number;
  private plugin: DiscourseGraphPlugin;
  private nodes: SearchableNode[];
  private query = "";
  private activeIndex = 0;
  private groups: SummonMenuGroup[] = [];
  private containerEl: HTMLElement;
  private root: Root;
  private scope: Scope;
  private resizeObserver: ResizeObserver;
  private cleanupListeners: (() => void)[] = [];

  constructor({ plugin, view, triggerFrom, trigger }: NodeSummonMenuOptions) {
    this.plugin = plugin;
    this.view = view;
    this.triggerFrom = triggerFrom;
    this.trigger = trigger;
    // Loaded once per opening; typing only re-ranks.
    this.nodes = new QueryEngine(plugin.app).getSearchableNodes(
      plugin.settings.nodeTypes,
    );

    const doc = view.dom.ownerDocument;
    this.containerEl = doc.body.createDiv({
      cls: "suggestion-container dg-node-summon-menu",
    });
    this.root = createRoot(this.containerEl.createDiv());

    // Parented to app.scope so unrelated hotkeys keep working while the menu is open.
    this.scope = new Scope(plugin.app.scope);
    this.scope.register([], "ArrowDown", () => this.move(1));
    this.scope.register([], "ArrowUp", () => this.move(-1));
    this.scope.register([], "Enter", () => {
      if (this.itemCount() === 0) {
        this.close();
        return true;
      }
      this.select(this.activeIndex);
      return false;
    });
    this.scope.register([], "Escape", () => {
      this.close();
      return false;
    });
    plugin.app.keymap.pushScope(this.scope);

    const closeIfOutside = (event: MouseEvent): void => {
      if (this.containerEl.contains(event.target as Node)) return;
      this.close();
    };
    doc.addEventListener("mousedown", closeIfOutside, true);
    this.cleanupListeners.push(() =>
      doc.removeEventListener("mousedown", closeIfOutside, true),
    );

    this.resizeObserver = new ResizeObserver(() => this.reposition());
    this.resizeObserver.observe(this.containerEl);

    this.render();
  }

  setQuery(query: string): void {
    if (query === this.query) return;
    this.query = query;
    this.activeIndex = 0;
    this.render();
  }

  close(): void {
    for (const cleanup of this.cleanupListeners) cleanup();
    this.cleanupListeners = [];
    this.plugin.app.keymap.popScope(this.scope);
    this.resizeObserver.disconnect();
    // Deferred: unmounting during React's event handling warns.
    const root = this.root;
    (this.view.dom.ownerDocument.defaultView ?? window).setTimeout(
      () => root.unmount(),
      0,
    );
    this.containerEl.remove();
    if (activeMenu === this) activeMenu = null;
  }

  private itemCount(): number {
    return this.groups.reduce((count, group) => count + group.nodes.length, 0);
  }

  private move(delta: number): boolean {
    const count = this.itemCount();
    // Nothing to move through, so the editor gets the arrow key.
    if (count === 0) return true;
    this.activeIndex = (this.activeIndex + delta + count) % count;
    this.render();
    return false;
  }

  private select(index: number): void {
    const node = this.groups.flatMap((group) => group.nodes)[index];
    if (!node) return;

    const sourcePath = this.view.state.field(editorInfoField, false)?.file?.path;
    const link = this.plugin.app.fileManager.generateMarkdownLink(
      node.file,
      sourcePath ?? "",
    );
    const to = this.view.state.selection.main.head;
    const from = this.triggerFrom;

    this.close();
    this.view.dispatch({
      changes: { from, to, insert: link },
      selection: { anchor: from + link.length },
      userEvent: "input.complete",
    });
    this.view.focus();
  }

  private render(): void {
    this.groups = groupNodesForSummonMenu({
      nodes: this.nodes,
      nodeTypes: this.plugin.settings.nodeTypes,
      query: this.query,
    });
    this.root.render(
      <NodeSummonList
        groups={this.groups}
        activeIndex={this.activeIndex}
        onSelect={(index) => this.select(index)}
        onHover={(index) => {
          if (index === this.activeIndex) return;
          this.activeIndex = index;
          this.render();
        }}
      />,
    );
  }

  // Editor layout can only be read in a measure phase, not during an update.
  private reposition(): void {
    this.view.requestMeasure({
      read: (view) => view.coordsAtPos(this.triggerFrom),
      write: (coords) => {
        if (!coords) return;
        const win = this.view.dom.ownerDocument.defaultView ?? window;
        const { width, height } = this.containerEl.getBoundingClientRect();
        const left = Math.min(
          Math.max(VIEWPORT_MARGIN, coords.left),
          Math.max(VIEWPORT_MARGIN, win.innerWidth - width - VIEWPORT_MARGIN),
        );
        const spaceBelow = win.innerHeight - coords.bottom;
        const openUpward =
          spaceBelow < height + VIEWPORT_MARGIN && coords.top > spaceBelow;
        const top = openUpward
          ? Math.max(VIEWPORT_MARGIN, coords.top - height - 4)
          : coords.bottom + 4;
        this.containerEl.style.left = `${left}px`;
        this.containerEl.style.top = `${top}px`;
      },
    });
  }
}

let activeMenu: NodeSummonMenu | null = null;

export const getActiveNodeSummonMenu = (): NodeSummonMenu | null => activeMenu;

export const openNodeSummonMenu = (options: NodeSummonMenuOptions): void => {
  activeMenu?.close();
  activeMenu = new NodeSummonMenu(options);
};

export const closeNodeSummonMenu = (): void => {
  activeMenu?.close();
};

/**
 * Where a just-typed trigger starts, or null. Like Roam, it must start the line
 * or follow whitespace, so `me@lab.org` doesn't open the menu.
 */
export const getTypedTriggerStart = ({
  lineBeforeCursor,
  trigger,
}: {
  lineBeforeCursor: string;
  trigger: string;
}): number | null => {
  if (!trigger || !lineBeforeCursor.endsWith(trigger)) return null;
  const start = lineBeforeCursor.length - trigger.length;
  const charBefore = lineBeforeCursor.charAt(start - 1);
  return start === 0 || /\s/.test(charBefore) ? start : null;
};

// Matches Roam's limit for the same setting.
export const MAX_NODE_SEARCH_TRIGGER_LENGTH = 5;

/** Returns an error message, or null when the trigger can be saved. */
export const validateNodeSearchTrigger = ({
  value,
  nodeTagHotkey,
}: {
  value: string;
  nodeTagHotkey: string;
}): string | null => {
  if (value.length > MAX_NODE_SEARCH_TRIGGER_LENGTH) {
    return `The trigger can be at most ${MAX_NODE_SEARCH_TRIGGER_LENGTH} characters.`;
  }
  // The node tag hotkey's keydown handler swallows the key, so it could never be typed.
  if (nodeTagHotkey && value.includes(nodeTagHotkey)) {
    return `The trigger can't contain the node tag hotkey (${nodeTagHotkey}).`;
  }
  return null;
};

