11	const updateOpenMenu = (update: ViewUpdate): boolean => {
12	  const menu = getActiveNodeSummonMenu();
13	  if (!menu || menu.view !== update.view) return false;
14	  if (!update.docChanged && !update.selectionSet) return true;
15	
16	  const { doc, selection } = update.state;
17	  const triggerFrom = update.changes.mapPos(menu.triggerFrom);
18	  const queryFrom = triggerFrom + menu.trigger.length;
19	  const head = selection.main.head;
20	
21	  const triggerIntact =
22	    queryFrom <= doc.length &&
23	    doc.sliceString(triggerFrom, queryFrom) === menu.trigger;
24	  const cursorInQuery =
25	    selection.main.empty &&
26	    head >= queryFrom &&
27	    doc.lineAt(head).number === doc.lineAt(triggerFrom).number;
28	
29	  if (!triggerIntact || !cursorInQuery) {
30	    closeNodeSummonMenu();
31	    return true;
32	  }
33	
