cd /private/tmp/claude-501/-Users-trang-doan--claude-spares-spare-ItioIi/acd926ad-e46c-48ee-923d-2dbaf02f04e8/scratchpad && cat > eng-893-slice2.mjs <<'EOF'
// ENG-893 slice 2: trigger setting + menu hierarchy styling.
import slice1 from "./eng-893-slice1.mjs";
const MENU = ".dg-node-summon-menu";

const openGeneralSettings = (ctx) => ctx.client.evaluate(`return (async () => {
  app.setting.open(); app.setting.openTabById(${ctx.json(ctx.vault.pluginId)});
  await new Promise(r => setTimeout(r, 400));
  const root = app.setting.activeTab.containerEl;
  [...root.querySelectorAll("button, div")].find(b => b.textContent.trim() === "General" && b.onclick !== undefined && b.children.length === 0)?.click();
  await new Promise(r => setTimeout(r, 300));
  return true; })();`);

// Settings is its own window, so drive the React input with that window's native setter.
const setTrigger = (ctx, value) => ctx.client.evaluate(`return (async () => {
  const root = app.setting.activeTab.containerEl;
  const row = [...root.querySelectorAll(".setting-item")].find(r => r.querySelector(".setting-item-name")?.textContent === "Node search trigger");
  if (!row) return { found: false };
  const input = row.querySelector("input");
  const win = input.ownerDocument.defaultView;
  Object.getOwnPropertyDescriptor(win.HTMLInputElement.prototype, "value").set.call(input, ${ctx.json(value)});
  input.dispatchEvent(new win.Event("input", { bubbles: true }));
  await new Promise(r => setTimeout(r, 200));
  const errors = [...row.querySelectorAll(".setting-item-description")].slice(1).map(e => e.textContent);
  return { found: true, inputValue: input.value, saved: app.plugins.plugins[${ctx.json(ctx.vault.pluginId)}].settings.nodeSearchTrigger, errors };
})();`);

const closeSettings = (ctx) => ctx.client.evaluate(`app.setting.close(); return true;`);
const restore = async (ctx) => {
  await ctx.client.evaluate(`return (async () => { const p = app.plugins.plugins[${ctx.json(ctx.vault.pluginId)}];
    p.settings.nodeSearchTrigger = "@"; await p.saveSettings(); app.setting.close(); return true; })();`);
};

const typeAndCheck = async (ctx, text) => {
  const { client, json } = ctx;
  const p = await ctx.writeNote("summon-scratch.md", "");
  await client.evaluate(`return (async () => { const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(p)}), { state: { mode: "source", source: true } });
    app.workspace.setActiveLeaf(leaf, { focus: true }); leaf.view.editor.focus(); return true; })();`);
  await client.typeText(text);
  await new Promise((r) => setTimeout(r, 500));
  return client.evaluate(`!!document.querySelector(${json(MENU)})`);
};

export default [
  {
    name: "Menu: type headers stand apart from nodes",
    input: "type @ in Live Preview",
    expected: "uppercase headers with a colour dot and divider; rows indented past the dot",
    run: async (ctx) => {
      await slice1[0].run(ctx);
      return ctx.client.evaluate(`return (() => {
        const m = document.querySelector(${ctx.json(MENU)});
        const headers = [...m.querySelectorAll(".suggestion > div:not(.suggestion-item)")];
        const item = m.querySelector(".suggestion-item");
        const h = headers[0], cs = getComputedStyle(h);
        return { headers: headers.length, transform: cs.textTransform, dot: !!h.querySelector("span.rounded-full"),
          divider: headers[1] ? getComputedStyle(headers[1]).borderTopStyle : "n/a",
          itemPad: parseFloat(getComputedStyle(item).paddingLeft), headerPad: parseFloat(cs.paddingLeft) };
      })();`);
    },
    expect: (a) => ({
      pass: a.transform === "uppercase" && a.dot && (a.headers < 2 || a.divider === "solid") && a.itemPad > a.headerPad,
      actual: JSON.stringify(a),
    }),
  },
  {
    name: "Setting: custom trigger applies without reload",
    input: "Settings window (DOM events): set trigger to ;; then type ;; in a note",
    expected: "saved as ;;, no error; ;; opens the menu, @ does not",
    run: async (ctx) => {
      await openGeneralSettings(ctx);
      const set = await setTrigger(ctx, ";;");
      await closeSettings(ctx);
      const opensNew = await typeAndCheck(ctx, ";;");
      await ctx.client.pressEscape();
      const opensOld = await typeAndCheck(ctx, "@");
      return { set, opensNew, opensOld };
    },
    expect: (a) => ({
      pass: a.set.found && a.set.saved === ";;" && a.set.errors.length === 0 && a.opensNew && !a.opensOld,
      actual: JSON.stringify(a),
    }),
    teardown: restore,
  },
  {
    name: "Setting: invalid triggers show an error and aren't saved",
    input: "set trigger to '\\\\' (node tag hotkey), then '@@@@@@'",
    expected: "error shown each time; saved trigger stays @",
    run: async (ctx) => {
      await openGeneralSettings(ctx);
      const hotkey = await setTrigger(ctx, "\\");
      const long = await setTrigger(ctx, "@@@@@@");
      return { hotkey, long };
    },
    expect: (a) => ({
      pass: a.hotkey.errors.length === 1 && a.hotkey.saved === "@" && a.long.errors.length === 1 && a.long.saved === "@",
      actual: JSON.stringify(a),
    }),
    teardown: restore,
