  const { client, json } = ctx;
  const p = await ctx.writeNote(name, content);
  await client.evaluate(`return (async () => { const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(p)}), { state: { mode: "source", source: true } });
    app.workspace.setActiveLeaf(leaf, { focus: true }); const e = leaf.view.editor; e.focus();
    ${cursorAtEnd ? `const l = e.lastLine(); e.setCursor({ line: l, ch: e.getLine(l).length }); e.scrollIntoView({ from: e.getCursor(), to: e.getCursor() });` : ""}
    return true; })();`);
  return p;
};
const isOpen = (ctx) => ctx.client.evaluate(`!!document.querySelector(${ctx.json(MENU)})`);
const waitOpen = (ctx) => ctx.client.waitFor(`!!document.querySelector(${ctx.json(MENU)})`, { label: "menu open", timeoutMs: 3000 });
const click = async (ctx, x, y) => {
  for (const type of ["mousePressed", "mouseReleased"])
    await ctx.client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1 });
};
const text = (ctx) => ctx.client.evaluate(`return app.workspace.activeLeaf.view.editor.getValue();`);

export default [
  {
    name: "Cursor moved back into @text does not open",
    input: "note '@abc' with cursor at start; move cursor to end of line",
    expected: "no menu",
    run: async (ctx) => {
      await openNote(ctx, "summon-cursor.md", "@abc", false);
      await ctx.client.evaluate(`app.workspace.activeLeaf.view.editor.setCursor({ line: 0, ch: 1 }); app.workspace.activeLeaf.view.editor.setCursor({ line: 0, ch: 4 }); return true;`);
      await sleep(400);
      return isOpen(ctx);
    },
    expect: (open) => ({ pass: !open, actual: `open=${open}` }),
  },
  {
    name: "Near the bottom it opens above the cursor, inside the window",
    input: "80-line note, cursor on last line scrolled to the bottom; type @",
    expected: "menu bottom is above the cursor line; menu fully inside the window",
    run: async (ctx) => {
      await openNote(ctx, "summon-bottom.md", Array.from({ length: 80 }, (_, i) => `line ${i}`).join("\n") + "\n");
      await sleep(300);
      await ctx.client.typeText("@");
      await waitOpen(ctx);
      await sleep(300);
      return ctx.client.evaluate(`return (() => { const m = document.querySelector(${ctx.json(MENU)}).getBoundingClientRect();
        const cm = app.workspace.activeLeaf.view.editor.cm; const c = cm.coordsAtPos(cm.state.selection.main.head);
        return { menuTop: m.top, menuBottom: m.bottom, cursorTop: c.top, cursorBottom: c.bottom, winH: innerHeight, winW: innerWidth, left: m.left, right: m.right }; })();`);
    },
    expect: (a) => ({
      pass: a.menuBottom <= a.cursorTop && a.menuTop >= 0 && a.left >= 0 && a.right <= a.winW,
      actual: JSON.stringify(a),
    }),
  },
  {
    name: "Clicking a result inserts it, editor keeps focus",
    input: "type @, mouse-click the second result",
    expected: "link to the clicked node replaces @; menu closes; cursor after link",
    run: async (ctx) => {
      await openNote(ctx, "summon-click.md", "");
      await ctx.client.typeText("@");
      await waitOpen(ctx);
      const target = await ctx.client.evaluate(`return (() => { const i = document.querySelectorAll(${ctx.json(MENU + " .suggestion-item")})[1];
        const r = i.getBoundingClientRect(); return { title: i.textContent, x: r.left + r.width / 2, y: r.top + r.height / 2 }; })();`);
      await click(ctx, target.x, target.y);
      await sleep(300);
      const after = await ctx.client.evaluate(`return (() => { const e = app.workspace.activeLeaf.view.editor;
        return { text: e.getValue(), ch: e.getCursor().ch, focused: document.activeElement?.classList.contains("cm-content") }; })();`);
      return { target, after, open: await isOpen(ctx) };
    },
    expect: (a) => ({
      pass: !a.open && a.after.text.includes(a.target.title) && !a.after.text.includes("@") && a.after.ch === a.after.text.length && a.after.focused,
      actual: `clicked=${a.target.title} text=${a.after.text} ch=${a.after.ch} focused=${a.after.focused} open=${a.open}`,
    }),
  },
  {
    name: "Clicking outside closes",
    input: "type @, click the note title",
    expected: "menu closes; @ stays",
    run: async (ctx) => {
      await openNote(ctx, "summon-outside.md", "");
      await ctx.client.typeText("@");
      await waitOpen(ctx);
      const pt = await ctx.client.evaluate(`return (() => { const r = app.workspace.activeLeaf.view.containerEl.querySelector(".view-header-title-container, .view-header").getBoundingClientRect();
        return { x: r.left + 10, y: r.top + r.height / 2 }; })();`);
      await click(ctx, pt.x, pt.y);
      await sleep(300);
      return { open: await isOpen(ctx), text: await text(ctx) };
    },
    expect: (a) => ({ pass: !a.open && a.text === "@", actual: JSON.stringify(a) }),
  },
  {
    name: "Switching notes closes",
    input: "type @, then activate another note's tab",
    expected: "menu closes",
    run: async (ctx) => {
      const other = await ctx.writeNote("summon-other.md", "other");
      await openNote(ctx, "summon-switch.md", "");
      await ctx.client.typeText("@");
      await waitOpen(ctx);
      await ctx.client.evaluate(`return (async () => { const leaf = app.workspace.getLeaf("tab");
        await leaf.openFile(app.vault.getAbstractFileByPath(${ctx.json(other)})); app.workspace.setActiveLeaf(leaf, { focus: true }); return true; })();`);
      await sleep(400);
      return isOpen(ctx);
    },
    expect: (open) => ({ pass: !open, actual: `open=${open}` }),
  },
];
EOF
